from collections import deque

def has_diagonal_1_connected_to_0(grid, r, c):
    h, w = len(grid), len(grid[0])
    q = deque([(r, c)])
    visited = {(r, c)}

    while q:
        cr, cc = q.popleft()
        for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in visited:
                if grid[nr][nc] == 1:
                    if nr < h-1 and nc > 0 and grid[nr+1][nc-1] == 0:
                        return True
                    if nr < h-1 and nc < w-1 and grid[nr+1][nc+1] == 0:
                        return True
                    if nr > 0 and nc > 0 and grid[nr-1][nc-1] == 0:
                        return True
                    if nr > 0 and nc < w-1 and grid[nr-1][nc+1] == 0:
                        return True
                    visited.add((nr, nc))
                    q.append((nr, nc))
    return False

